using System;
using System.IO;
using UnityEngine;
using UnityEditor;

namespace Unity.AI.Assistant.Agent.Dynamic.Extension.Editor
{
    internal class CommandScript : IRunCommand
    {
        public void Execute(ExecutionResult result)
        {
            if (EditorApplication.isPlayingOrWillChangePlaymode || EditorApplication.isCompiling)
                throw new InvalidOperationException("Stable Edit mode required.");
            if (Path.GetFullPath(Application.dataPath).Replace('\\', '/') != "E:/work/mmorpg-client/Assets")
                throw new InvalidOperationException("Unexpected project.");
            MailSocialAssetImport.ImportApproved();
            result.Log("Approved mail and social sprites imported with source-pixel, size, border and GUID checks.");
        }
    }
}
